(()=>{const section=document.getElementById('experience');if(!section)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const roles=[...section.querySelectorAll('[data-experience-category]')],filters=[...section.querySelectorAll('[data-experience-filter]')],secondary=section.querySelector('.experience-secondary'),status=document.getElementById('experience-filter-status');filters.forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.experienceFilter;filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;roles.forEach(role=>{const visible=value==='all'||role.dataset.experienceCategory===value;role.hidden=!visible;if(visible){count++;if(!reduced){role.classList.remove('experience-role-in');requestAnimationFrame(()=>role.classList.add('experience-role-in'));}}});secondary.hidden=!roles.some(r=>r.dataset.experienceCategory==='operations'&&!r.hidden);status.textContent='Showing '+count+' '+(count===1?'role':'roles')+(value==='all'?'.':value==='research'?' in research and team leadership.':' in operations and service.');}));
if(!reduced&&'IntersectionObserver'in window){document.documentElement.classList.add('portfolio-motion');const targets=[...document.querySelectorAll('.experience-intro,.experience-feature,.experience-secondary article,.trajectory-intro,.trajectory-evidence')];const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('reveal-pending');entry.target.classList.add('reveal-visible');observer.unobserve(entry.target);}}),{threshold:.08});targets.forEach(target=>{target.classList.add('reveal-pending');observer.observe(target);});const counters=section.querySelectorAll('.experience-results strong');const counterObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const element=entry.target,original=element.textContent,value=parseFloat(original.replace(/[^\d.]/g,'')),prefix=original.includes('≈')?'≈':'',suffix=original.includes('%')?'%':original.includes('+')?'+':'';if(!Number.isFinite(value))return;let started;function tick(now){if(started===undefined)started=now;const progress=Math.min((now-started)/850,1);element.textContent=prefix+Math.round(value*(1-Math.pow(1-progress,3)))+suffix;if(progress<1)requestAnimationFrame(tick);else element.textContent=original;}element.classList.add('counting');requestAnimationFrame(tick);counterObserver.unobserve(element);}),{threshold:.5});counters.forEach(c=>counterObserver.observe(c));}
})();
